code.cpp:
#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    string s;
    cin >> s;

    string result = "";
    for (char ch : s) {
        if (ch >= 'a' && ch <= 'z') {
            result += (char) (ch - 'a' + 'A');
        } else if (ch >= 'A' && ch <= 'Z') {
            result += (char) (ch - 'A' + 'a');
        } else {
            result += ch;
        }
    }
    cout << result << endl;

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();

        String result = "";
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch >= 'a' && ch <= 'z') {
                result += (char) (ch - 'a' + 'A');
            } else if (ch >= 'A' && ch <= 'Z') {
                result += (char) (ch - 'A' + 'a');
            } else {
                result += ch;
            }
        }
        System.out.println(result);
    }
}
